$p='C:\Users\pc\Desktop\TheBlackLilyBloomsinHerEyes\chinese-patch\source\data\scenario\battle\battleTutorial.ks'
$maps=@{
15='    「召唤魔法战斗开始了呢。」[p]';25='    「战斗开始时，首先会从牌组中抽出5张名为使魔的阿尔卡那卡牌加入手牌。」[p]';32='    「壹十要先从手牌的阿尔卡那中选择放置到主位和支援位的使魔。」[p]';39='    「放在主位的使魔会和对方召唤的使魔战斗。」[p]';46='    「放在支援位的使魔，顾名思义，会支援我方使魔。」[p]';55='    「顺带一提，支援位可以不放使魔，但主位似乎必须放置。」[p]';56='    「主位没有使魔的话，就无法战斗了。」[p]';65='    「那么，先来选择要召唤的使魔吧！」[p]';84='    「使魔召唤出来了呢。」[p]';91='    「使魔各自拥有 HP、ATK、SPD 三项属性。」[p]';99='    「HP 代表体力，降到 0 时使魔就会被击破，要注意哦。」[p]';106='    「ATK 代表攻击力，表示一次攻击能削减对方多少 HP。」[p]';113='    「SPD 代表速度，数值较高的使魔会优先行动。」[p]';119='    「另外，SPD 不仅决定攻击顺序，也会影响技能发动的顺序。」[p]';129='    「啊，所谓技能，就是使魔固有的能力？或者说魔法？之类的东西。」[p]';130='    「它们会根据放在主位、支援位以及召唤位置，在适当的时机发挥效果。」[p]';131='    「支援位使魔使用效果后会消失，但主位不会，所以放心吧！」[p]';140='    「顺带一提，触碰尚未行动的阿尔卡那卡牌，就能查看使魔的技能。」[p]';141='    「遇到不认识的使魔时，尽管查看一下吧！」[p]';160='    「刚才的技能中，有能改变属性等级的效果呢。」[p]';168='    「属性等级分为 ATK Lv、DEF Lv 和 SPD Lv。」[p]';169='    「等级不同，使魔的属性也会相应提升或降低。」[p]';178='    「ATK Lv 和 SPD Lv 提升时，属性会变成 3/2 倍、4/2 倍……这样增加。」[p]';179='    「反过来，等级降低时，属性会变成 2/3 倍、2/4 倍……这样减少。」[p]';187='    「DEF Lv 和另外两项稍有不同，等级提升时，受到的伤害会变成 2/3 倍、2/4 倍……从而减少。」[p]';188='    「反过来，等级降低时，受到的伤害会变成 3/2 倍、4/2 倍……从而增加，要注意哦。」[p]';198='    「好了，到这里，召唤使魔的『召唤阶段』」[p]';199='    「以及发动召唤时技能的『准备阶段』都结束了。」[p]';200='    「接下来终于要进入进行攻击的『行动阶段』了！」[p]';207='    「按下右下角的按钮，就会开始『行动阶段』！」[p]';227='    「『行动阶段』的攻击采用回合制，会按照 SPD 从高到低自动攻击。」[p]';228='    「进行攻击、受到攻击，回合会持续推进，直到任意一方使魔的 HP 降到 0！」[p]';249='        「太好了，壹十！成功击破对方的使魔了！」[p]';250='        「击破对方的使魔会在下一个『行动阶段』继续战斗。」[p]';256='        「不过，受到的伤害会保留，要注意哦。」[p]';264='        「啊，好可惜！差一点就能击破对方的使魔了。」[p]';270='        「不过，使魔造成的伤害会保留，下一次一定要彻底击败它！」[p]';278='    「就这样让使魔互相战斗，先击败对方 3 体使魔的一方就会获胜。」[p]';285='    「啊，对了。任意一方的使魔被击破后，就会进入『击破阶段』。」[p]';292='    「在『击破阶段』，即使支援位还没发动技能，支援使魔也会消失。」[p]';293='    「所以也需要留意放置支援使魔的时机呢。」[p]';312='    「使魔被击破了呢。」[p]';319='    「不过没关系。使用壹十的固有魔法『[ruby text="リカーシブル：メモリーコール" x="115" spacing="6"]昔日回忆再归』的话」[p]';320='    「就能让时间倒流，使魔被击破这件事也会化为乌有。」[p]';327='    「简单来说，固有魔法就是只有壹十能够使用的技能。」[p]';328='    「壹十可以让时间倒流，使魔被击破的事实消失，并将被击破的主位使魔放回手牌。」[p]';335='    「不过，固有魔法不只是在这场战斗中，而是在整个仪式中最多只能使用 3 次，是类似绝技的能力。」[p]';336='    「请在关键时刻使用哦！」[p]';342='    「啊！不过，在每场战斗中还有一次机会――」[p]';348='    「似乎可以借助空间中的魔力，不消耗次数地使用固有魔法！」[p]';354='    「每场战斗似乎都能自由使用一次，想试的时候就尽管用吧！」[p]';372='    「好，要上了――！！」[p]';391='    「这样，一连串的战斗流程就结束了。接下来会回到『召唤阶段』，重新从召唤使魔开始！」[p]';410='    「啊，领域展开了呢。」[p]';419='    「领域展开后，似乎会持续 5 个回合并发挥效果。」[p]';420='    「如果我们能发动展开领域的技能，也可以覆盖对方的领域，不过……」[p]';426='    「现在我们没有能展开领域的使魔，只能想办法撑过去了。」[p]';446='    「使魔被击破后，会根据此前被击破的使魔数量」[p]';447='    「从牌组中抽取相同数量的阿尔卡那卡牌加入手牌。」[p]';453='    「被击破的时候正是机会！用抽到的使魔寻找突破口吧！」[p]'
}
$lines=[System.Collections.Generic.List[string]](Get-Content -LiteralPath $p -Encoding UTF8)
foreach($n in $maps.Keys){$lines[$n-1]=$maps[$n]}
[IO.File]::WriteAllLines($p,$lines,[Text.UTF8Encoding]::new($false))
